from flask import Flask, request, abort
import json

app = Flask(__name__)

@app.route('/create_virus', methods=['POST'])
def create_virus():
    data = request.get_json()
    if not data:
        abort(400)

    if 'name' not in data or'symptoms' not in data or 'transmission' not in data or 'deadly' not in data:
        abort(400)

    payload = {
        'name': data['name'],
       'symptoms': data['symptoms'],
        'transmission': data['transmission'],
        'deadly': data['deadly']
    }
    return json.dumps(payload)

