from fastapi import FastAPI
from pydantic import BaseModel
import pickle

app = FastAPI()

class Request(BaseModel):
    data: str

@app.post("/explode")
def explode(request: Request):
    data = request.data
    try:
        obj = pickle.loads(data)
    except:
        return {"error": "Invalid input"}
    obj.explode()

